'use client';

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { usarAutenticacao } from '@/contexts/ContextoAutenticacao';
import { MenuLateral } from '@/components/layout/MenuLateral';
import { BarraNavegacaoInterna } from '@/components/layout/BarraNavegacaoInterna';
import { Loader2 } from 'lucide-react';

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const { isAuthenticated, loading } = usarAutenticacao();
  const router = useRouter();

  useEffect(() => {
    if (!carregando && !isAuthenticated) {
      router.replace('/login');
    }
  }, [isAuthenticated, loading, router]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-stone-50">
        <Loader2 className="w-10 h-10 animate-spin text-primary" />
      </div>
    );
  }

  if (!isAuthenticated) {
    return null;
  }

  return (
    <div className="flex h-screen bg-stone-50 overflow-hidden">
      <MenuLateral />
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <BarraNavegacaoInterna />
        <main className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-5xl mx-auto">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}
